// One message answering two questions: what needs me, and what is stuck.
//
// Built from /export/applications because that is the only endpoint
// carrying titles and companies. The plain /applications list returns
// job_id only, so a digest built on it prints rows of blank names --
// which reads as a broken agent rather than a data-shape mistake.
//
// The ASK goes last on purpose. On a phone the last line is the one
// that gets acted on; a digest that buries it under statistics is read
// and then forgotten.

const nl = String.fromCharCode(10);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.status);

const waiting = rows.filter((r) => r.status === 'pending_review');
const queued  = rows.filter((r) => r.status === 'approved');
const applied = rows.filter((r) => r.status === 'submitted');

const lines = [];

if (waiting.length) {
  waiting.sort((a, b) => (b.score ?? 0) - (a.score ?? 0));
  lines.push(`${waiting.length} job${waiting.length === 1 ? '' : 's'} waiting for your yes:`, '');
  for (const a of waiting.slice(0, 10)) {
    lines.push(`  ${a.score ?? ''}  ${a.title ?? ''}`);
    if (a.company) lines.push(`      ${a.company}`);
    if (a.cover_letter_flagged) lines.push('      CHECK THE LETTER before approving');
  }
  if (waiting.length > 10) lines.push(`  ... and ${waiting.length - 10} more in the sheet`);
} else {
  lines.push('Nothing is waiting for your review.');
}

if (queued.length) {
  lines.push('', `${queued.length} on your shortlist, not applied to yet.`);
  lines.push('Open each one, read the letter, and apply yourself.');
}

lines.push('', `Applied so far: ${applied.length}`);

if (waiting.length) {
  lines.push('', 'To approve: open the sheet, type yes in the Approve? column.');
  lines.push('It moves to your shortlist within ten minutes.');
}

return [{ json: { title: 'Job hunt update', body: lines.join(nl) } }];
